  from: 'from',
  to: 'to',
  provider: 'p',
  type: 't',
  place: 'place',
  lat: 'lat',
  lon: 'lon',
  zoom: 'z',
  selected: 'sel',
  view: 'view',
  sort: 'sort',
  overlay: 'ov',
  otime: 'ot',
